def gen(rng):
    def fmt(a, b, c):
        return ' '.join(str(len(x)) for x in (a, b, c)) + '\n' + '\n'.join(' '.join(map(str, x)) for x in (a, b, c))
    tests = [fmt([1], [1], [1]), fmt([1], [2], [3]), fmt([1, 1], [2], [1, 1]), fmt([5, 5], [5], [10]),
             fmt([3, 4, 1, 2], [5, 2, 3], [2, 4, 3]), fmt([1, 1], [5], [2, 3])]
    for n in (2, 3, 4, 6, 8):
        for _ in range(3):
            tests.append(fmt(*[[rng.randint(1, 5) for _ in range(rng.randint(1, n))] for _ in range(3)]))
    for n in (3, 5, 8, 10):
        for _ in range(3):
            common = [rng.randint(1, 6) for _ in range(rng.randint(1, 4))]
            parts = []
            for _ in range(3):
                parts.append([rng.randint(1, 6) for _ in range(rng.randint(0, n))] + common)
            tests.append(fmt(*parts))
    N = 10**5
    tests.append(fmt(*[[rng.randint(1, 10**5) for _ in range(N)] for _ in range(3)]))
    tests.append(fmt([1] * N, [1] * N, [1] * N))
    common = [rng.randint(1, 10**5) for _ in range(30000)]
    tests.append(fmt(*[[rng.randint(1, 10**5) for _ in range(70000)] + common for _ in range(3)]))
    tests.append(fmt([10**5] * N, [1] * N, [rng.randint(1, 10) for _ in range(N)]))
    tests.append(fmt([1] * N, [2] * (N // 2), [4] * (N // 4)))
    return tests
